using System.Diagnostics;
using System.Runtime.InteropServices;
namespace ScreenshotTranslationUiTester;
internal sealed class GlobalMouseBindingHost:IDisposable
{
    internal bool IsHookInstalled=>_hook!=IntPtr.Zero;
    private const int WhMouseLl=14,LDown=0x201,RDown=0x204,MDown=0x207,XDown=0x20B,Wheel=0x20A;private readonly Func<InputBinding,bool> _protectedContext;private readonly Func<InputBinding,bool> _capture;private readonly Action<string> _trace;private readonly Dictionary<InputActionId,(InputBinding Binding,Action Trigger)> _bindings=[];private readonly HookProc _proc;private IntPtr _hook;
    internal GlobalMouseBindingHost(Func<InputBinding,bool> protectedContext,Func<InputBinding,bool> capture,Action<string> trace){_protectedContext=protectedContext;_capture=capture;_trace=trace;_proc=Hook;}
    internal void Apply(IEnumerable<(InputActionId Action,InputBinding Binding,Action Trigger)> values){_bindings.Clear();foreach(var value in values.Where(x=>x.Binding.Kind is InputBindingKind.MouseButton or InputBindingKind.MouseWheel))_bindings[value.Action]=(value.Binding,value.Trigger);EnsureHook();}
