    private void EnsureHook(){if(_hook!=IntPtr.Zero)return;using var process=Process.GetCurrentProcess();using var module=process.MainModule!;_hook=SetWindowsHookEx(WhMouseLl,_proc,GetModuleHandle(module.ModuleName),0);}
    private IntPtr Hook(int code,IntPtr wp,IntPtr lp){if(code<0)return CallNextHookEx(_hook,code,wp,lp);var message=wp.ToInt32();if(message is not (LDown or RDown or MDown or XDown or Wheel))return CallNextHookEx(_hook,code,wp,lp);var data=Marshal.PtrToStructure<MouseData>(lp);var mods=CurrentModifiers();var win=(GetAsyncKeyState(Keys.LWin)&0x8000)!=0||(GetAsyncKeyState(Keys.RWin)&0x8000)!=0;InputBinding binding=message switch{LDown=>new(InputBindingKind.MouseButton,MouseButton:InputMouseButton.Left,Ctrl:mods.HasFlag(Keys.Control),Alt:mods.HasFlag(Keys.Alt),Shift:mods.HasFlag(Keys.Shift),Win:win),RDown=>new(InputBindingKind.MouseButton,MouseButton:InputMouseButton.Right,Ctrl:mods.HasFlag(Keys.Control),Alt:mods.HasFlag(Keys.Alt),Shift:mods.HasFlag(Keys.Shift),Win:win),MDown=>new(InputBindingKind.MouseButton,MouseButton:InputMouseButton.Middle,Ctrl:mods.HasFlag(Keys.Control),Alt:mods.HasFlag(Keys.Alt),Shift:mods.HasFlag(Keys.Shift),Win:win),XDown=>new(InputBindingKind.MouseButton,MouseButton:(data.ButtonData>>16)==1?InputMouseButton.XButton1:InputMouseButton.XButton2,Ctrl:mods.HasFlag(Keys.Control),Alt:mods.HasFlag(Keys.Alt),Shift:mods.HasFlag(Keys.Shift),Win:win),_=>new(InputBindingKind.MouseWheel,Wheel:(short)(data.ButtonData>>16)>0?InputWheelDirection.Up:InputWheelDirection.Down,Ctrl:mods.HasFlag(Keys.Control),Alt:mods.HasFlag(Keys.Alt),Shift:mods.HasFlag(Keys.Shift),Win:win)};_trace($"Hook Msg=0x{message:X} Injected={(data.Flags&1)!=0} Modifiers={mods} Candidate={binding.DisplayName}");if(_capture(binding)){_trace("CaptureSessionOwnsInput=YES GlobalDispatch=SUPPRESSED UiMessage=SUPPRESSED");return new IntPtr(1);}if(_protectedContext(binding)){_trace("ContextProtected=YES Dispatch=PASS_THROUGH");return CallNextHookEx(_hook,code,wp,lp);}foreach(var (_,entry) in _bindings)if(entry.Binding==binding){_trace($"GlobalDispatch Action Binding={binding.DisplayName}");entry.Trigger();break;}return CallNextHookEx(_hook,code,wp,lp);}
    private static Keys CurrentModifiers(){var r=Keys.None;if((GetAsyncKeyState(Keys.ControlKey)&0x8000)!=0)r|=Keys.Control;if((GetAsyncKeyState(Keys.Menu)&0x8000)!=0)r|=Keys.Alt;if((GetAsyncKeyState(Keys.ShiftKey)&0x8000)!=0)r|=Keys.Shift;return r;}
