    private delegate IntPtr HookProc(int c,IntPtr w,IntPtr l);[StructLayout(LayoutKind.Sequential)]private struct MouseData{public Point Point;public uint ButtonData,Flags,Time;public IntPtr Extra;}
    [DllImport("user32.dll",SetLastError=true)]private static extern IntPtr SetWindowsHookEx(int id,HookProc proc,IntPtr module,uint thread);[DllImport("user32.dll")]private static extern bool UnhookWindowsHookEx(IntPtr hook);[DllImport("user32.dll")]private static extern IntPtr CallNextHookEx(IntPtr hook,int code,IntPtr wp,IntPtr lp);[DllImport("kernel32.dll",CharSet=CharSet.Auto)]private static extern IntPtr GetModuleHandle(string? name);[DllImport("user32.dll")]private static extern short GetAsyncKeyState(Keys key);
}
